65		data, err := os.ReadFile(filepath.Join(deviceDir, "uevent"))
66		if err != nil {
67			return fmt.Sprintf("GPU %d", index)
68		}
69		for _, line := range strings.Split(string(data), "\n") {
70			if v, ok := strings.CutPrefix(line, "PCI_SLOT_NAME="); ok {
71				return v
72			}
73		}
74		return fmt.Sprintf("GPU %d", index)
75	}
