88		m := GPUMetrics{Index: g.Index, Name: g.Name}
89		m.BusyPct = readSysInt(filepath.Join(g.SysPath, "gpu_busy_percent"))
90		m.VRAMTotal = readSysUint64(filepath.Join(g.SysPath, "mem_info_vram_total"))
91		m.VRAMUsed = readSysUint64(filepath.Join(g.SysPath, "mem_info_vram_used"))
92	
93		if hwmon := g.resolveHwmon(); hwmon != "" {
94			m.TempC = float64(readSysInt64(filepath.Join(hwmon, "temp1_input"))) / 1000.0
95			m.PowerW = float64(readSysInt64(filepath.Join(hwmon, "power1_average"))) / 1_000_000.0
