101	// path is stale (hwmon index can change across driver reloads).
102	func (g *GPUInfo) resolveHwmon() string {
103		if g.hwmon != "" {
104			if _, err := os.Stat(g.hwmon); err == nil {
105				return g.hwmon
106			}
107			g.hwmon = "" // stale; re-resolve below
108		}
109		matches, err := filepath.Glob(filepath.Join(g.SysPath, "hwmon/hwmon*"))
110		if err != nil || len(matches) == 0 {
111			return ""
112		}
113		g.hwmon = matches[0]
114		return g.hwmon
115	}
