1	package cli
2	
3	import (
4		"context"
5		"fmt"
6		"log/slog"
7		"os"
8		"os/signal"
9		"syscall"
10	
11		"github.com/nogo/wire/internal"
12		"github.com/nogo/wire/internal/config"
13		"github.com/nogo/wire/internal/gateway"
14		"github.com/nogo/wire/internal/monitor"
15		"github.com/nogo/wire/internal/process"
16		"github.com/nogo/wire/internal/vram"
17	)
18	
19	const usageText = `Usage: wire <command> [arguments]
20	
21	Commands:
22	  up                  Start the gateway (foreground)
23	  version             Print version and exit
24	
25	Environment:
26	  WIRE_CONFIG         Config file path (default: ~/.config/wire/config.yaml)
27	`
28	
29	// Run dispatches CLI commands from the given argument slice (os.Args[1:]).
30	// It returns an exit code suitable for os.Exit.
31	func Run(args []string) int {
32		if err := dispatch(args); err != nil {
33			fmt.Fprintln(os.Stderr, "wire:", err)
34			return 1
35		}
36		return 0
37	}
38	
39	func dispatch(args []string) error {
40		if len(args) == 0 {
41			fmt.Print(usageText)
42			return nil
43		}
44		switch args[0] {
45		case "help", "--help", "-h":
46			fmt.Print(usageText)
47			return nil
48		case "up":
49			return runUp()
50		case "version", "--version", "-v":
51			fmt.Printf("wire %s (%s) built %s\n", internal.Version, internal.Commit, internal.BuildDate)
52			return nil
53		default:
54			fmt.Print(usageText)
55			return fmt.Errorf("unknown command: %q", args[0])
56		}
57	}
58	
59	func runUp() error {
60		cfg, err := config.Load()
61		if err != nil {
62			return fmt.Errorf("loading config: %w", err)
63		}
64	
65		// bgCtx drives the process manager; cancelled only after gateway drains.
66		bgCtx, bgCancel := context.WithCancel(context.Background())
67		defer bgCancel()
68	
69		// shutCtx is cancelled by SIGTERM/SIGINT.
70		shutCtx, stop := signal.NotifyContext(bgCtx, syscall.SIGTERM, syscall.SIGINT)
71		defer stop()
72	
73		// 2. VRAM tracker init (GPU auto-detect, HF cache scan).
74		backend := detectGPUBackend(cfg)
75		tracker := vram.New(backend, vram.NewHFCache(cfg.HFCacheDir))
76		gpus := tracker.Discover()
77		tracker.HFCache().Scan()
78		tracker.Start()
79		defer tracker.Stop()
80	
81		for _, model := range cfg.Warmup {
82			if estimate := tracker.EstimateForModel(model); estimate > 0 && !tracker.CanFit(estimate) {
83				slog.Warn("warmup model exceeds available VRAM; will attempt load anyway",
84					"model", model, "estimate_bytes", estimate, "free_vram_bytes", tracker.FreeVRAM())
85			}
86		}
87	
88		// 3. Process manager init.
89		mgr := process.New(cfg, slog.Default())
90		if err := mgr.Start(bgCtx); err != nil {
91			return fmt.Errorf("starting process manager: %w", err)
92		}
93	
94		// Create remote tracker if any model references a provider.
95		var remote *monitor.RemoteTracker
96		for _, p := range cfg.Models {
97			if p.IsRemote() {
98				remote = monitor.NewRemoteTracker()
99				break
100			}
101		}
102	
103		// Create model discovery for providers that have list_models enabled.
104		var discovery *monitor.ModelDiscovery
105		if len(cfg.Providers) > 0 {
106			var endpoints []monitor.ProviderEndpoint
107			for name, p := range cfg.Providers {
108				if p.ShouldListModels() {
109					endpoints = append(endpoints, monitor.ProviderEndpoint{
110						Name:    name,
111						BaseURL: p.BaseURL,
112						APIKey:  p.APIKey,
113					})
114				}
115			}
116			if len(endpoints) > 0 {
117				discovery = monitor.NewModelDiscovery(endpoints, slog.Default())
118				discovery.Start()
119				defer discovery.Stop()
120			}
121		}
122	
123		// 4. Hub init (subscribes to VRAM tracker for GPU state).
124		var hub *monitor.Hub
125		if cfg.Monitor {
126			hub = monitor.NewHub(slog.Default(), mgr.Events(), mgr.Snapshot, remote, discovery, tracker.GPUStateCh())
127		}
128	
129		// 5. Gateway init (uses VRAM tracker + queue).
130		gw := gateway.New(cfg, mgr, hub, remote, discovery, slog.Default())
131	
132		if hub != nil {
133			hub.SetModelProvider(func() []monitor.ModelInfo {
134				return gw.Models()
135			})
136			hub.Start()
137			defer hub.Stop()
138		}
139	
140		// 6. Warmup models submitted through gateway's admission path.
141		// (Warmup via gateway is deferred to a follow-up WU.)
142	
143		gwErrCh := make(chan error, 1)
144		go func() { gwErrCh <- gw.ListenAndServe(shutCtx) }()
145	
146		var reloadCh <-chan *config.Config
147		if ch, err := config.Watch(bgCtx, slog.Default()); err != nil {
148			slog.Warn("config watcher unavailable", "err", err)
149		} else {
150			reloadCh = ch
151		}
152	
153		slog.Info("wire ready", "listen", cfg.Listen, "version", internal.Version, "commit", internal.Commit, "gpus", len(gpus))
154	
155		for {
156			select {
157			case err := <-gwErrCh:
158				bgCancel()
159				_ = mgr.Stop()
160				if err != nil {
161					return fmt.Errorf("gateway error: %w", err)
162				}
163				return nil
164	
165			case <-shutCtx.Done():
166				if cause := context.Cause(shutCtx); cause != nil {
167					slog.Info("shutting down", "cause", cause)
168				}
169				stop()
170				if err := <-gwErrCh; err != nil {
171					slog.Error("gateway shutdown error", "error", err)
172				}
173				bgCancel()
174				return mgr.Stop()
175	
176			case newCfg, ok := <-reloadCh:
177				if !ok || newCfg == nil {
178					reloadCh = nil
179					continue
180				}
181				if newCfg.Listen != cfg.Listen {
182					slog.Warn("listen address change requires restart")
